import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def compare_metric_values(
    namespace: str,
    metric_name: str,
    resource1_dimensions: Dict[str, str],
    resource2_dimensions: Dict[str, str],
    start_time,
    end_time,
    period: int = 300,
    stat: str = "Average",
    unit: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Compare Amazon CloudWatch metric values for two resources/dimension filters over the same window.

    Returns a dictionary containing per-resource series, summaries, and pointwise differences.
    """
    if region_name is None:
        region_name = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")

    session = boto3.Session(region_name=region_name)
    client = session.client("cloudwatch")

    def build_metric_stat(dimensions: Dict[str, str]) -> Dict[str, Any]:
        dims = [{"Name": k, "Value": v} for k, v in sorted(dimensions.items())]
        metric_stat: Dict[str, Any] = {
            "Metric": {
                "Namespace": namespace,
                "MetricName": metric_name,
                "Dimensions": dims,
            },
            "Period": period,
            "Stat": stat,
        }
        if unit is not None:
            metric_stat["Metric"]["Unit"] = unit
        return metric_stat

    def fetch_series(dimensions: Dict[str, str]) -> List[Dict[str, Any]]:
        try:
            paginator = client.get_paginator("get_metric_statistics")
            # get_metric_statistics is a single-call API, but a paginator interface is not provided;
            # use direct call for clarity.
            response = client.get_metric_statistics(
                Namespace=namespace,
                MetricName=metric_name,
                Dimensions=[{"Name": k, "Value": v} for k, v in sorted(dimensions.items())],
                StartTime=start_time,
                EndTime=end_time,
                Period=period,
                Statistics=[stat],
                **({"Unit": unit} if unit is not None else {}),
            )
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"CloudWatch metric fetch failed: {e}") from e

        datapoints = response.get("Datapoints", [])
        datapoints.sort(key=lambda x: x["Timestamp"])
        value_key = stat
        normalized = []
        for dp in datapoints:
            normalized.append(
                {
                    "timestamp": dp["Timestamp"].isoformat() if hasattr(dp["Timestamp"], "isoformat") else dp["Timestamp"],
                    "value": dp.get(value_key),
                }
            )
        return normalized

    series1 = fetch_series(resource1_dimensions)
    series2 = fetch_series(resource2_dimensions)

    def summarize(series: List[Dict[str, Any]]) -> Dict[str, Any]:
        values = [dp["value"] for dp in series if dp["value"] is not None]
        return {
            "count": len(values),
            "min": min(values) if values else None,
            "max": max(values) if values else None,
            "avg": (sum(values) / len(values)) if values else None,
            "sum": sum(values) if values else None,
        }

    # Align on timestamps present in either series; preserve time ordering.
    map1 = {dp["timestamp"]: dp["value"] for dp in series1}
    map2 = {dp["timestamp"]: dp["value"] for dp in series2}
    all_timestamps = sorted(set(map1) | set(map2))

    comparisons = []
    for ts in all_timestamps:
        v1 = map1.get(ts)
        v2 = map2.get(ts)
        delta = None
        ratio = None
        if v1 is not None and v2 is not None:
            delta = v1 - v2
            ratio = (v1 / v2) if v2 not in (0, 0.0) else None
        comparisons.append(
            {
                "timestamp": ts,
                "resource1_value": v1,
                "resource2_value": v2,
                "delta": delta,
                "ratio": ratio,
            }
        )

    return {
        "provider": "aws_cloudwatch",
        "namespace": namespace,
        "metric_name": metric_name,
        "window": {
            "start_time": start_time.isoformat() if hasattr(start_time, "isoformat") else start_time,
            "end_time": end_time.isoformat() if hasattr(end_time, "isoformat") else end_time,
            "period": period,
            "stat": stat,
            "unit": unit,
        },
        "resource1": {
            "dimensions": resource1_dimensions,
            "series": series1,
            "summary": summarize(series1),
        },
        "resource2": {
            "dimensions": resource2_dimensions,
            "series": series2,
            "summary": summarize(series2),
        },
        "comparisons": comparisons,
    }
